"""Hilbert function of a T = 1 box under a cyclic group generated by a coordinate permutation sigma of order g,
via isotypic decomposition mod p (p = 1 mod g).  Over Q the nontrivial isotypic components come in Galois orbits;
for g prime all g-1 nontrivial characters are conjugate, so H = H_0 + (g-1) H_1 when computed over Q; we compute
every block mod p anyway (cheap) and report per-block data.
Usage: cycgen.py <profile> L maxdeg <mult>   (sigma: x -> mult*x on F_q coordinates)
"""
import sys, time
import numpy as np
import flint
from sympy import isprime
from flib import *
from model import profile


def find_prime(g, start):
    p = start - (start % g) + 1
    while not isprime(p):
        p -= g
    return p


def act(k, perm):
    out = [0] * len(k)
    for x, v in enumerate(k):
        out[perm[x]] = v
    return tuple(out)


def orbit_reps(items, perm, g):
    seen = set(); reps = []
    for k in items:
        if k in seen:
            continue
        orb = [k]
        cur = k
        for _ in range(g - 1):
            cur = act(cur, perm)
            orb.append(cur)
        seen |= set(orb)
        reps.append((k, len(set(orb))))
    return reps


def hilbert_gen(A, perm, g, maxdeg, p, verbose=True):
    d = len(A[0])
    Aset = set(A)
    assert all(act(k, perm) in Aset for k in A), 'sigma does not preserve A'
    preps = orbit_reps(A, perm, g)
    mons = []
    for j in range(maxdeg + 1):
        mons += reduced_monomials(d, j)
    mreps = orbit_reps(mons, perm, g)
    mreps.sort(key=lambda r: (sum(r[0]), r[0]))
    mdeg = [sum(a) for a, _ in mreps]
    h = 2
    while pow(h, (p - 1) // g, p) == 1:
        h += 1
    w = pow(h, (p - 1) // g, p)
    # images of point reps under sigma^j
    imgs = []
    for k, _ in preps:
        cur = k; row = [k]
        for _ in range(g - 1):
            cur = act(cur, perm); row.append(cur)
        imgs.append(row)
    Mon = np.array([a for a, _ in mreps], dtype=np.int64)
    Htot = {}
    perblock = []
    for s in range(g):
        rows = [i for i, (k, sz) in enumerate(preps) if sz == g or (s * sz) % g == 0 and sz == g] if s else list(range(len(preps)))
        # for s != 0 keep only free orbits (non-free orbits project to zero unless character trivial on stabiliser)
        if s:
            rows = [i for i, (k, sz) in enumerate(preps) if sz == g]
        acc = np.zeros((len(rows), len(mreps)), dtype=object)
        for j in range(g):
            cj = pow(w, (-s * j) % g, p)
            P = np.array([imgs[i][j] for i in rows], dtype=np.int64)
            # value of monomial a at point P: prod P_x^{a_x}; for ternary P: 0 if a_x>0 and P_x=0; sign from odd exps
            V = np.ones((len(rows), len(mreps)), dtype=np.int64)
            for x in range(d):
                ax = Mon[:, x]
                px = P[:, x][:, None]
                V = V * np.where(ax[None, :] == 0, 1, np.where(ax[None, :] == 1, px, px * px))
            acc = (acc + V.astype(object) * cj) % p
        Mm = flint.nmod_mat(len(rows), len(mreps), [int(x) for x in acc.ravel()], p)
        prev = 0; Hs = []
        for j in range(maxdeg + 1):
            ncols = sum(1 for dg in mdeg if dg <= j)
            sub = flint.nmod_mat(len(rows), ncols, [int(Mm[i, c]) for i in range(len(rows)) for c in range(ncols)], p)
            r = sub.rank()
            Hs.append(r - prev); prev = r
        perblock.append(Hs)
        for j, v in enumerate(Hs):
            Htot[j] = Htot.get(j, 0) + v
        if verbose:
            print('  block s=%d rows=%d H_s=%s' % (s, len(rows), Hs), flush=True)
    return len(preps), len(mreps), [Htot[j] for j in range(maxdeg + 1)], perblock


if __name__ == '__main__':
    name = sys.argv[1]; L = int(sys.argv[2]); maxdeg = int(sys.argv[3]); mult = int(sys.argv[4])
    M, pats = profile(name)
    q = M - 1
    perm = [(mult * x) % q for x in range(q)]
    g = 1; cur = mult % q
    while cur != 1:
        cur = (cur * mult) % q; g += 1
    A = box(M, pats, L)
    p = find_prime(g, 1 << 58)
    t = time.time()
    npo, nmo, H, pb = hilbert_gen(A, perm, g, maxdeg, p)
    print('%s L=%d |A|=%d group order %d p=%d point orbits=%d mono orbits=%d H(0..%d)=%s sum=%d (%.1fs)' % (
        name, L, len(A), g, p, npo, nmo, maxdeg, H, sum(H), time.time() - t), flush=True)
